"""Render the local UX critique as a self-contained annotated HTML artifact."""
from pathlib import Path
import json,base64,html
root=Path('docs/qa/rebuild')
findings=json.loads((root/'findings.json').read_text())
walks=json.loads((root/'walkthroughs.json').read_text())
balance=json.loads((root/'balance.json').read_text())
esc=html.escape
images={}
for f in ['before-draft.png','before-game.png','walk-desktop-0.png','walk-desktop-5.png','walk-touch-4.png','walk-desktop-7.png']:
 p=root/f
 if p.exists():images[f]='data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
head='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chalk & Dynasty — rebuild review</title><style>body{font:16px/1.6 system-ui;background:#101c24;color:#e7f0ed;margin:0}main{max-width:1080px;margin:auto;padding:36px 22px}h1{line-height:1.1;font-size:42px}h2{margin-top:40px}p{color:#b9cbd1}a{color:#b6ee8d}.tag{font-size:11px;text-transform:uppercase;letter-spacing:.1em;background:#31543d;border-radius:4px;padding:5px 8px;color:#cff2b3}.finding{border:1px solid #415760;border-radius:8px;padding:22px;margin:15px 0;background:#192c37}.finding h3{margin:7px 0}code{font-size:12px;color:#bdcfdf}figure{margin:20px 0;position:relative}img{max-width:100%;display:block;border:1px solid #45606a;border-radius:8px}.phone img{max-width:390px;margin:auto}.callout{position:absolute;border:3px solid #ff9d68;pointer-events:none;border-radius:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid #39505a;padding:10px}.small{font-size:12px;color:#9eb6bf}.count{font-size:27px;color:#b6ee8d}.pass{color:#b6ee8d}details{margin:12px 0}summary{cursor:pointer;color:#b6ee8d}@media(max-width:650px){.grid{grid-template-columns:1fr}h1{font-size:32px}}</style><main><span class="tag">Local disposable build · UX review</span><h1>A basketball game you can<br>draw your own ideas into.</h1><p>The review uses the Agent Team Kit’s expectation → action → observation → judgment loop. Baseline: 97d822dc. Real browser behavior, local disposable saves, ordinary randomness. This is an agent-conducted review, not an independent human playtest or proof that everyone will find it fun.</p>'''
body=[]
livefile=root/'live-verification.json'
if livefile.exists():
 live=json.loads(livefile.read_text())
 body.append(f'<p class="tag">Published and verified · HTTPS {live["http"]} · {live["assetCount"]} matching asset hashes · 6 live desktop/touch checks passed</p><p><a href="{esc(live["url"])}">Play the live rebuild</a></p>')
body.append('<h2>What changed</h2><p>A court-centered arena, direct ball/shooter choices, four editable plays, inferred screens and rolls, automatic passing, optional playable coaching, short contextual feedback and immediate rematches. Historical data and one-player-per-position drafts are preserved.</p>')
body.append('<div class="grid"><figure><img data-image="before-game.png" alt="Original dashboard-style game"><figcaption>Before: court and possession choices spread across a long dashboard.</figcaption><i class="callout" style="left:73%;top:20%;width:24%;height:30%"></i></figure><figure><img data-image="walk-desktop-5.png" alt="Rebuilt arena"><figcaption>After: the court, score, roles and next action remain together.</figcaption></figure></div>')
body.append('<h2>Findings and resolutions</h2>')
for f in findings:
 body.append(f'<article class="finding"><span class="tag">{esc(f["severity"])} · {esc(f["status"])}</span><h3>{esc(f["id"])} — {esc(f["title"])}</h3><p><b>Expected:</b> {esc(f["expected"])}</p><p><b>Observed:</b> {esc(f["observed"])}</p><p><b>Fix:</b> {esc(f["fix"])}</p><details><summary>Reproduce / verify</summary><p>{esc(f["repro"])}</p><code>{esc(f["code"])}</code><p>{esc(f.get("verification","Covered by the rebuilt-game browser and mechanics checks."))}</p></details></article>')
body.append('<h2>Actual playthroughs</h2><p>These recorded runs started with fresh drafts and used visible mouse or touch controls. No state injection, forced wins or random-function replacement. Playback ran at normal speed; decisions were automated, so these durations are not human session-time estimates.</p><table><tr><th>Run</th><th>Possessions</th><th>Rematches</th><th>Elapsed</th><th>Result</th></tr>')
for w in walks:
 body.append(f'<tr><td>{esc(w["name"])}</td><td>{sum(x["attempts"] for x in w["levels"])}</td><td>{sum(x["retries"] for x in w["levels"])}</td><td>{w["durationSeconds"]} s</td><td class="pass">All five beaten · {len(w["errors"])} page errors</td></tr>')
body.append('</table><p class="small">Complete shot outcomes, rosters, screenshots and recording paths are in walkthroughs.json. Browser regression runs additionally complete the ladder with ordinary randomness.</p>')
body.append('<div class="grid"><figure class="phone"><img data-image="walk-touch-4.png" alt="Phone playthrough"><figcaption>Touch controls, court and primary action fit together.</figcaption></figure><figure><img data-image="walk-desktop-7.png" alt="Final victory"><figcaption>The full run reaches the trophy with the drafted five.</figcaption></figure></div>')
s=balance['summary']
body.append(f'<h2>Fairness check</h2><p><span class="count">{balance["lineups"]}</span> different valid drafted teams; {balance["uniquePlayers"]} distinct identities. {s["completed"]} simulated ladders completed, with a median of {s["medianPossessions"]} possessions, a 90th percentile of {s["p90Possessions"]}, and {s["meanRetries"]:.2f} average rematches. The simulation measures the model, not player satisfaction.</p><table><tr><th>Opponent</th><th>Simple strategy</th><th>Bucket chance</th><th>Standing still</th><th>Round win chance</th></tr>')
for l in balance['levels']:
 t=next(t for t in l['templates'] if t['id']==l['strategy'])
 body.append(f'<tr><td>{l["level"]}</td><td>{esc(l["strategy"])}</td><td>{t["meanBucketRate"]:.0%}</td><td>{l["stationaryBucketRate"]:.0%}</td><td>{t["meanRoundWinRate"]:.0%}</td></tr>')
body.append('</table><p class="small">120 seeded random valid drafts, predeclared strategies by opponent; no best-play oracle. Equivalent independent bucket/miss distributions include interception risk. Full method and every outcome: balance.json. A human pacing estimate is roughly 5–10 minutes including drafting and time to think; it has not been measured in human playtests.</p>')
body.append('<h2>Control sweep</h2><p>Verified: all five draft positions and blocked repeats; player details/search; ball and shot choice; all four plays; Move/Draw/Pass; undo; clear versus reset; direct and manual delivery; optional practice; ordinary makes/misses/interceptions; retry/advance/victory; saved-game resume; sound preference; keyboard edits; modal Escape; new-draft cancel/confirm. Current tests are recorded in VALIDATION.md.</p><p>Intentional limits: source links are validated as attributed URLs without clicking every off-site record; sound preference and cue invocation are tested but subjective loudness is not automatically judged. Physical phones, Safari/Firefox and an independent human usability review remain untested. Moving-screen fouls, rebounds and detailed contact physics are outside this arcade model.</p><p>QA reference: <a href="https://github.com/ai-foundry-byu/agent-team-kit/tree/c3ed7ad31d4a299f60a3aa6959f051d7f98847ae">Agent Team Kit</a>. No hooks, hosted feedback backend or release pipeline were installed. Broad critique stayed local; the live site receives a targeted post-release smoke check.</p>')
(root/'review.html').write_text(head+''.join(body)+'<script>const images='+json.dumps(images)+';document.querySelectorAll("[data-image]").forEach(e=>e.src=images[e.dataset.image]);</script></main></html>')
print('Wrote',root/'review.html')
